//! `bsc memory brief` — what a LAUNCHING SESSION is told about the nodes it is about to touch.
//!
//! # Why this exists
//!
//! A session both READS memory at launch and WRITES it during the run, so what session N learned
//! reaches session N+1 keyed by the code they share. That loop only closes if the reading half is
//! automatic: a worker that must choose to run a query will not run it, because the whole value of
//! memory is catching the thing you did not know to look for.
//!
//! The query itself already existed — `bsc memory list --link <ref>` is the back-reference resolver,
//! computed, with nothing stored on the record. What was missing is the CALLERS. This module is the
//! one renderer they share: `ensure_worktree` at launch, the Glance node overlay, and a live session
//! asking mid-run. Three call sites and one definition of "related", rather than three free to
//! disagree.
//!
//! # KIND decides inlined vs pointed-at
//!
//! | kind | how it reaches the session | why |
//! |---|---|---|
//! | `lesson` | inlined | literally do-not-step-on-this-again, and there are few |
//! | `highlight` | inlined when related | a decision about the architecture is what a worker most needs and least often finds |
//! | `record` | a POINTER | highest precision, but highest volume once the comment harvest lands |
//! | `ambient` | never | an unpromoted capture is noise by definition — that is why it is a review queue |
//! | `note` | never | unclassified means unreviewed; injecting it would make that queue a way to reach every session without anyone deciding |
//!
//! # The copy, and why it is allowed HERE
//!
//! The worker protocol says the store WINS over anything quoted into the context, because a quoted
//! body is a second copy and the copy is what a worker edits while the record keeps the old one.
//! Inlining a memory is exactly that shape. It is permitted here, and only here, because a memory IS
//! a snapshot of what was believed at a moment (maintainer, 2026-09-08) — a source that changed later
//! makes the memory history, not wrong. The rendered block says so, and prints the command that gets
//! the live answer.

use crate::{Memory, HORIZON_NOW, KIND_HIGHLIGHT, KIND_LESSON, KIND_RECORD};

/// The heading the block is written under. Also the idempotence marker: `ensure_worktree` replaces the
/// block when it is already present rather than appending a second one, so a relaunch converges.
pub const MARKER: &str = "What we remember about this work";

/// Total inlined memories, across both groups. A block nobody finishes reading has injected nothing,
/// so the cap is the point rather than a safety valve.
pub const MAX_INLINE: usize = 12;
/// How many STANDING lessons ride along. Deliberately small: they are the general traps, and the
/// session-specific half is what this exists to deliver.
pub const MAX_STANDING: usize = 4;

/// Is this memory eligible to be INLINED at all — regardless of whether it is related?
///
/// `now` only: a `future` memory is a hope, and a block headed "what we remember" must not mix a hope
/// into what is known. `open` only: `done` means acted on or folded elsewhere.
fn inlinable(m: &Memory) -> bool {
    m.horizon.eq_ignore_ascii_case(HORIZON_NOW) && m.status.eq_ignore_ascii_case("open")
}

/// Does this memory link to ANY of `refs`? The back-reference query, one memory at a time.
fn touches(m: &Memory, refs: &[String]) -> bool {
    refs.iter().any(|r| m.links_to(r))
}

/// What a session is told, computed. Borrowed from the store so nothing is cloned to render it.
#[derive(Debug)]
pub struct Brief<'a> {
    /// Lessons and highlights edged to something this session touches — the session-specific half.
    pub about_this_work: Vec<&'a Memory>,
    /// Lessons carrying NO edge at all. An unlinked lesson is one nobody scoped to anything, which is
    /// what makes it general — so the orphan queue earns a use here rather than being only a chore.
    pub standing: Vec<&'a Memory>,
    /// Related `record` notes — counted and reachable by command, never inlined.
    pub record_notes: usize,
    /// Related memories that did not make the inlined tier (capped out, `future`, or `done`).
    pub not_shown: usize,
}

impl Brief<'_> {
    /// Is there anything at all to say? A `false` here still renders a block — see [`render`].
    pub fn is_empty(&self) -> bool {
        self.about_this_work.is_empty() && self.standing.is_empty() && self.record_notes == 0
    }
}

/// Select what this session is told, from the whole store and the refs it will touch.
///
/// Ordering is newest-first within each group, matching `filter_and_order`, so the brief and
/// `bsc memory list` never disagree about which memory is the most recent.
pub fn brief<'a>(memories: &'a [Memory], refs: &[String]) -> Brief<'a> {
    let mut sorted: Vec<&Memory> = memories.iter().collect();
    sorted.sort_by(|a, b| b.created_at_ms.cmp(&a.created_at_ms).then(b.id.cmp(&a.id)));

    let related: Vec<&Memory> = sorted.iter().copied().filter(|m| touches(m, refs)).collect();

    let mut about: Vec<&Memory> = related
        .iter()
        .copied()
        .filter(|m| inlinable(m) && (m.is_kind(KIND_LESSON) || m.is_kind(KIND_HIGHLIGHT)))
        .collect();
    let record_notes = related.iter().filter(|m| m.is_kind(KIND_RECORD)).count();

    // The standing lessons: unlinked, so never scoped to anything, so general. Excluded if they are
    // somehow already in `about` (they cannot be — an unlinked memory touches no ref — but the filter
    // is written anyway so a future change to `touches` cannot silently double-print one).
    let mut standing: Vec<&Memory> = sorted
        .iter()
        .copied()
        .filter(|m| inlinable(m) && m.is_kind(KIND_LESSON) && m.links.is_empty())
        .filter(|m| !about.iter().any(|a| a.id == m.id))
        .take(MAX_STANDING)
        .collect();

    // The session-specific half is what this exists to deliver, so it keeps its budget first and the
    // standing lessons take whatever is left — never the other way round.
    about.truncate(MAX_INLINE);
    let room = MAX_INLINE.saturating_sub(about.len());
    standing.truncate(room);

    let shown: usize = about.len();
    let not_shown = related
        .iter()
        .filter(|m| m.is_kind(KIND_LESSON) || m.is_kind(KIND_HIGHLIGHT))
        .count()
        .saturating_sub(shown);

    Brief { about_this_work: about, standing, record_notes, not_shown }
}

/// The exact command that gets the LIVE answer for these refs — printed in every block, including the
/// empty one, because the store is what wins and a reader must always be one copy-paste from it.
pub fn command(refs: &[String]) -> String {
    match refs.first() {
        Some(r) => format!("bsc memory list --link {r}"),
        None => "bsc memory list".to_string(),
    }
}

fn bullet(m: &Memory) -> String {
    let tags = if m.tags.is_empty() { String::new() } else { format!(" _({})_", m.tags.join(", ")) };
    // The text verbatim, on one line. A memory is written as prose and re-wrapping it here would be a
    // second formatting of something already formatted by its author.
    format!("- **{}** — {}{tags}\n", m.kind, m.text.trim())
}

/// Render the block written into a worker's `CLAUDE.local.md`.
///
/// ZERO RELATED MEMORIES STILL RENDERS A BLOCK, and that is deliberate. "Nothing is recorded about
/// these nodes" and "nobody looked" are different facts, and an absent block says the second while
/// meaning the first — the same defect `inject_required_algorithms` had when a stream that resolved
/// to no feature was indistinguishable from a feature that required nothing, in silence, for 52 of
/// 89 streams. The empty block says it is empty and names the verb that fills it.
pub fn render(b: &Brief, refs: &[String]) -> String {
    let cmd = command(refs);
    let mut out = format!("## {MARKER}\n\n");

    if b.is_empty() {
        out.push_str(
            "Nothing is recorded against the nodes this work touches. That is not the same as there \
             being nothing to know — it means no session has written it down yet.\n\n\
             Be the one that does: `bsc memory add '<what you learned>' --kind lesson --link about:<record-id>`\n",
        );
        return out;
    }

    out.push_str(
        "Captured by earlier sessions, edged to the records, features and plan refs this work \
         touches. **These are SNAPSHOTS** — what was believed when they were written. The store is \
         live and wins over anything quoted here; re-read it before you act on one:\n\n",
    );
    out.push_str(&format!("    {cmd}\n\n"));

    if !b.about_this_work.is_empty() {
        out.push_str("### About this work\n\n");
        for m in &b.about_this_work {
            out.push_str(&bullet(m));
        }
        out.push('\n');
    }
    if !b.standing.is_empty() {
        out.push_str("### Standing lessons\n\nNot scoped to anything, which is what makes them general.\n\n");
        for m in &b.standing {
            out.push_str(&bullet(m));
        }
        out.push('\n');
    }
    if b.record_notes > 0 || b.not_shown > 0 {
        out.push_str("### More, by command\n\n");
        if b.record_notes > 0 {
            // Named by COUNT, never inlined: record notes are the highest-precision memories a worker
            // can get — they are about the very records it owns — and, once the comment harvest lands,
            // by far the most numerous. Quoting them would bury the two sections above.
            out.push_str(&format!(
                "- {} note(s) harvested from comments in these records: `{cmd} --kind record`\n",
                b.record_notes
            ));
        }
        if b.not_shown > 0 {
            out.push_str(&format!("- {} more related memor(ies) beyond the cap: `{cmd}`\n", b.not_shown));
        }
        out.push('\n');
    }
    out.push_str("Write what YOU learn back the same way, so the next session starts where you finished.\n");
    out
}
